package com.bank.cheque;

import java.util.logging.*;

public class ConsecutiveDemo {
    private static final Logger log = Logger.getLogger(ConsecutiveDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Jumbled cheque serial numbers from batch processing
        int[] serials = {100, 4, 200, 1, 3, 2, 101, 102, 103};

        SequenceFinder finder = new SequenceFinder();
        int longest = finder.longestConsecutive(serials);

        log.info("Finding the longest run of consecutive cheque serials");
        log.info("Longest consecutive run length -> " + longest);
    }
}

// ─── Would be in service/SequenceFinder.java ───
class SequenceFinder {
    // HashSet + expand only from true starts. O(n) time, O(n) space.
    int longestConsecutive(int[] nums) {
        java.util.Set<Integer> set = new java.util.HashSet<>();
        for (int x : nums) set.add(x);          // dedupe + O(1) lookups

        int best = 0;
        for (int x : set) {
            if (!set.contains(x - 1)) {         // x is a true start of a run
                int current = x, length = 1;
                while (set.contains(current + 1)) {
                    current++;
                    length++;
                }
                best = Math.max(best, length);
            }
        }
        return best;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
